import{_ as o,C as t,o as a,c as i,ag as d,E as s}from"./chunks/framework.cyF4XceO.js";const _=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),n={name:"docs/versions.md"};function c(l,e,m,h,u,p){const r=t("StatusNote");return a(),i("div",null,[e[0]||(e[0]=d('<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>Takoform has four independent current version streams: the Host API, each Form definition, Core/library software, and Provider software. A version on one axis is not a maturity label for another axis. The Form Package API identifier is a wire/envelope format, not a fifth product stream.</p><h2 id="current-publisher-corpus" tabindex="-1">Current publisher corpus <a class="header-anchor" href="#current-publisher-corpus" aria-label="Permalink to &quot;Current publisher corpus&quot;">​</a></h2><p>The official current corpus is one versionless family, <code>edge.forms.takoform.com</code>, with 16 exact Experimental <code>0.x</code> Forms, 7 Interfaces, and 6 Bindings. The source roster is pinned to <a href="https://github.com/tako0614/takoform-forms/tree/3a395e4d7f9f652a942da52905857fccc41b467e" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3a395e4</code></a>.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Current identity</th><th>Meaning</th></tr></thead><tbody><tr><td>Host API</td><td><strong><code>forms.takoform.com/v1</code></strong></td><td>Stable wire contract for discovery, exact Form availability, operations, fencing, and errors.</td></tr><tr><td>Form</td><td>Each Form&#39;s <strong><code>definitionVersion</code></strong></td><td>Exact independently versioned contract; the official corpus has 16 Experimental Forms in one family.</td></tr><tr><td>Core/library</td><td>Independent software SemVer</td><td>SDK, verifier, compiler, and CLI releases; they do not version the Host API or a Form.</td></tr><tr><td>Provider</td><td>Independent software SemVer</td><td>Typed tooling for Forms it explicitly supports; Provider publication does not widen the Form corpus.</td></tr><tr><td>Form Package</td><td><strong><code>packages.forms.takoform.com/v1alpha5</code></strong></td><td>Data envelope/wire format for Form packages, not a product release axis.</td></tr></tbody></table><p>The canonical <code>registry.terraform.io/tako0614/takoform</code> Provider is an official-Forms-only tool. Third-party Form packages use the same Host API path and package/verification contracts under their own namespaces, with explicit Provider mappings. A module can combine the official Takoform Provider with other Takoform or industry-standard Providers.</p><h2 id="provider-release-history-and-publication-boundary" tabindex="-1">Provider release history and publication boundary <a class="header-anchor" href="#provider-release-history-and-publication-boundary" aria-label="Permalink to &quot;Provider release history and publication boundary&quot;">​</a></h2><p>Provider <code>3.0.0</code> is the released Registry implementation. Its immutable projection contains the historical 8-family/31-resource aggregate; that release record is not the current publisher corpus. The official-only mapping for the current Edge16 source is a next-major candidate and is not published, so no future Provider install claim is made here. Examples requiring <code>&gt;=3.1.0</code> are candidate/unpublished until a release record says otherwise.</p><table tabindex="0"><thead><tr><th>Distribution</th><th>Host API</th><th>Form projection</th><th>Status</th></tr></thead><tbody><tr><td>Provider 3.0.0</td><td>Host API v1</td><td>Historical 8-family/31-resource Provider projection</td><td>Released Registry artifact; immutable history, not the current publisher roster.</td></tr><tr><td>Future official-only Provider</td><td>Host API v1</td><td>Edge16 publisher corpus</td><td>Next-major candidate; unpublished and not installable.</td></tr><tr><td>Provider 2.1.1</td><td>Host API v1beta1</td><td>Retained Edge v1beta1 identities</td><td>Immutable historical Registry client; exact pin only.</td></tr><tr><td>Provider 2.0.0 / 1.0.3</td><td>Withdrawn pre-Beta epochs</td><td>Retired identities</td><td>Immutable history for recovery and migration.</td></tr></tbody></table><p>Provider release, Form publication, and host availability are independent facts. A published Provider mapping does not publish a Form Package or change Form maturity.</p><h2 id="current-edge-form-links" tabindex="-1">Current Edge Form links <a class="header-anchor" href="#current-edge-form-links" aria-label="Permalink to &quot;Current Edge Form links&quot;">​</a></h2><p>The 16 current Forms are:</p><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code></a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code></a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code></a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code></a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code></a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code></a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code></a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code></a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code></a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code></a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code></a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code></a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code></a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code></a></li><li><a href="/docs/resources/durable_workflow.html"><code>takoform_durable_workflow</code></a></li><li><a href="/docs/resources/actor_namespace.html"><code>takoform_actor_namespace</code></a></li></ul><h2 id="specification-receipts-and-withdrawn-lanes" tabindex="-1">Specification receipts and withdrawn lanes <a class="header-anchor" href="#specification-receipts-and-withdrawn-lanes" aria-label="Permalink to &quot;Specification receipts and withdrawn lanes&quot;">​</a></h2><p>Specification 1.0/1.1 receipts are archive evidence, not a current version lane. They do not mint an API v1.1 route, Form <code>1.0.0</code>, or Provider release. The pre-Beta Host API epochs and their Provider clients remain available only under exact historical pins for recovery and migration; see the <a href="/release/">historical release records</a> and the <a href="/release/migrations/v2-to-v3.html">v2 to v3 migration boundary</a>.</p>',15)),s(r)])}const b=o(n,[["render",c]]);export{_ as __pageData,b as default};
